IF OBJECT_ID(N'[dbo].[BAYRAK_{{FIRMA}}_{{DONEM}}_FATURARAPOR]', N'V') IS NOT NULL DROP VIEW [dbo].[BAYRAK_{{FIRMA}}_{{DONEM}}_FATURARAPOR];
GO
CREATE VIEW [dbo].[BAYRAK_{{FIRMA}}_{{DONEM}}_FATURARAPOR] AS       select     CLCARD.CODE AS [Cari Hesap Kodu],  CLCARD.DEFINITION_ AS [Cari Hesap Adı],  CLCARD.SPECODE AS [Cari Özel Kod],CLCARD.SPECODE2 AS [Cari Özel Kod2],CLCARD.SPECODE3 AS [Cari Özel Kod3],  MUHASEBE.[Hesap Kodu] AS [Muhasebe Fiş Muhasebe Kodu],  MUHASEBE.[Hesap Adı]  AS [Muhasebe Fiş Muhasebe Adı],    CASE WHEN ISYERI.NR IN ('008','009') THEN ISYERI.NR    WHEN   ISNULL(INVOICE.SPECODE,'')='' THEN ISYERI.NR  ELSE TANIMLI.NR        END  AS [İş Yeri No],  CASE WHEN ISYERI.NR IN ('008','009') THEN ISYERI.NAME    WHEN  ISNULL(INVOICE.SPECODE,'')='' THEN ISYERI.NAME     ELSE  TANIMLI.NAME      END   AS [İş Yeri],  AMBAR.NAME as [Depo Adı],  INVOICE.FICHENO AS [Fatura No],  INVOICE.DOCODE  AS [Belge No],  ISNULL(INVOICE.SPECODE,'') AS [Özel Kod],  INVOICE.DATE_ AS [Tarih],  year(INVOICE.DATE_)  [Yıl],  RIGHT('00'+CAST(MONTH(INVOICE.DATE_) AS NVARCHAR(100)),2)+'-'+  CASE MONTH(INVOICE.DATE_)      WHEN 1 THEN 'Ocak'      WHEN 2 THEN 'Şubat'      WHEN 3 THEN 'Mart'      WHEN 4 THEN 'Nisan'      WHEN 5 THEN 'Mayıs'      WHEN 6 THEN 'Haziran'      WHEN 7 THEN 'Temmuz'      WHEN 8 THEN 'Ağustos'      WHEN 9 THEN 'Eylül'      WHEN 10 THEN 'Ekim'      WHEN 11 THEN 'Kasım'      WHEN 12 THEN 'Aralık'  END AS [Ay],  CASE WHEN STLINE.TRCODE  IN (7,8,9) THEN 'Satış' else 'İade' end  [Fiş Türü],       SATIS.CODE AS [Satış Elemanı],  CASE STLINE.LINETYPE   WHEN 0 THEN 'Malzeme'   WHEN 1 THEN 'Promosyon'   WHEN 2 THEN 'İndirim'   WHEN 3 THEN 'Masraf'   WHEN 4 THEN 'Hizmet'   WHEN 5 THEN 'Depozito'   WHEN 6 THEN 'Karma Koli'   WHEN 7 THEN 'Karma Koli Kalemi'   WHEN 8 THEN 'Sabit Kıymet'   WHEN 9 THEN 'Ek Malzeme'   WHEN 10 THEN 'Malzeme sınıfı'  WHEN 11 THEN 'Fason' ELSE '' END AS [Satır Türü],  CASE WHEN  STLINE.LINETYPE NOT IN (4) then  ıtems.CODE ELSE SRVCARD.code end as [Stok Kodu],  CASE WHEN  STLINE.LINETYPE NOT IN (4) then  ıtems.NAME ELSE SRVCARD.DEFINITION_ end AS [Stok Adı],  ITEMS.SPECODE  AS [Stok Özel Kod],  ITEMS.SPECODE2 AS [Stok Özel Kod2],  ITEMS.SPECODE3 AS [Stok Özel Kod3],  ITEMS.SPECODE4 AS [Stok Özel Kod4],  ITEMS.SPECODE5 AS [Stok Özel Kod5],  BIRIM.CODE AS [Ana Birim],  STLINE.AMOUNT*(CASE WHEN STLINE.UINFO2=0 THEN 1 ELSE STLINE.UINFO2 END/CASE WHEN STLINE.UINFO1=0 THEN 1 ELSE STLINE.UINFO1 END ) * (CASE WHEN STLINE.TRCODE  IN (7,8,9) THEN 1 else -1 end) [Ana Birim Miktar],      STLINE.LINENET * (CASE WHEN STLINE.TRCODE IN (7,8,9) THEN 1 ELSE -1 END) AS [Net Tutar],    (STLINE.AMOUNT *   (CASE WHEN STLINE.UINFO2 = 0 THEN 1 ELSE STLINE.UINFO2 END /    CASE WHEN STLINE.UINFO1 = 0 THEN 1 ELSE STLINE.UINFO1 END) *   (CASE WHEN STLINE.TRCODE IN (7,8,9) THEN 1 ELSE -1 END)   ) * STLINE.OUTCOST AS [Giriş Maliyeti],       (      (STLINE.LINENET * (CASE WHEN STLINE.TRCODE IN (7,8,9) THEN 1 ELSE -1 END))      -      (          (STLINE.AMOUNT *           (CASE WHEN STLINE.UINFO2 = 0 THEN 1 ELSE STLINE.UINFO2 END /            CASE WHEN STLINE.UINFO1 = 0 THEN 1 ELSE STLINE.UINFO1 END) *           (CASE WHEN STLINE.TRCODE IN (7,8,9) THEN 1 ELSE -1 END)          ) * STLINE.OUTCOST      )  ) AS [Kar Tutarı],       CASE      WHEN STLINE.LINENET = 0 THEN 0      ELSE          (              (                  (STLINE.LINENET * (CASE WHEN STLINE.TRCODE IN (7,8,9) THEN 1 ELSE -1 END))                  -                  (                      (STLINE.AMOUNT *                       (CASE WHEN STLINE.UINFO2 = 0 THEN 1 ELSE STLINE.UINFO2 END /                        CASE WHEN STLINE.UINFO1 = 0 THEN 1 ELSE STLINE.UINFO1 END) *                       (CASE WHEN STLINE.TRCODE IN (7,8,9) THEN 1 ELSE -1 END)                      ) * STLINE.OUTCOST                  )              ) * 100.0          ) / ABS(STLINE.LINENET)  END AS [Kar Oranı %]       from LG_{{FIRMA}}_{{DONEM}}_STLINE  STLINE        WITH(NOLOCK) LEFT JOIN   LG_{{FIRMA}}_{{DONEM}}_STFICHE  STFICHE WITH (NOLOCK) ON STFICHE.LOGICALREF = STLINE.STFICHEREF  LEFT JOIN LG_{{FIRMA}}_ITEMS  ITEMS        WITH(NOLOCK) ON ITEMS.LOGICALREF = STLINE.STOCKREF   AND STLINE.LINETYPE NOT IN (4)  LEFT JOIN LG_{{FIRMA}}_SRVCARD  SRVCARD        WITH(NOLOCK) ON SRVCARD.LOGICALREF = STLINE.STOCKREF   AND STLINE.LINETYPE   IN (4)  INNER JOIN LG_{{FIRMA}}_{{DONEM}}_INVOICE  INVOICE WITH(NOLOCK) ON INVOICE.LOGICALREF = STLINE.INVOICEREF  LEFT JOIN LG_{{FIRMA}}_CLCARD CLCARD       WITH(NOLOCK) ON CLCARD.LOGICALREF = STLINE.CLIENTREF  LEFT JOIN LG_{{FIRMA}}_UNITSETL BIRIM      WITH(NOLOCK) ON BIRIM.LOGICALREF = STLINE.UOMREF    LEFT JOIN LG_SLSMAN SATIS            WITH(NOLOCK) ON SATIS.LOGICALREF = STLINE.SALESMANREF  LEFT JOIN L_CAPIWHOUSE AMBAR         WITH(NOLOCK) ON AMBAR.NR = STLINE.SOURCEINDEX  AND AMBAR.FIRMNR='{{FIRMA}}'  LEFT JOIN LG_{{FIRMA}}_UNITSETL SATIRBIRIM WITH(NOLOCK) ON  SATIRBIRIM.LOGICALREF = STLINE.UOMREF   LEFT JOIN L_CAPIDIV   ISYERI ON ISYERI.NR = INVOICE.BRANCH   AND ISYERI.FIRMNR='{{FIRMA}}'   LEFT JOIN L_CAPIUSER EKLEYEN ON EKLEYEN.NR = INVOICE.CAPIBLOCK_CREATEDBY  LEFT JOIN   (  select ISYERI.NR,ISYERI.NAME,AMBAR.NR AMBARNO   FROM L_CAPIDIV  ISYERI   INNER JOIN L_CAPIWHOUSE  AMBAR ON AMBAR.DIVISNR = ISYERI.NR   WHERE ISYERI.FIRMNR='{{FIRMA}}' AND AMBAR.FIRMNR='{{FIRMA}}'  ) AS TANIMLI ON TANIMLI.AMBARNO=ISNULL(INVOICE.SPECODE,'')  AND  ISNULL(INVOICE.SPECODE,'')<>''      LEFT JOIN   (  SELECT EMFICHE.LOGICALREF,
 STUFF((SELECT ',' + CC2.CODE FROM LG_{{FIRMA}}_{{DONEM}}_EMFLINE EM2 LEFT JOIN LG_{{FIRMA}}_EMUHACC CC2 ON CC2.LOGICALREF=EM2.ACCOUNTREF WHERE EM2.ACCFICHEREF=EMFICHE.LOGICALREF AND SUBSTRING(CC2.CODE,1,1) IN ('6') FOR XML PATH(''), TYPE).value('.','NVARCHAR(MAX)'),1,1,'') AS [Hesap Kodu],
 STUFF((SELECT ',' + CC2.DEFINITION_ FROM LG_{{FIRMA}}_{{DONEM}}_EMFLINE EM2 LEFT JOIN LG_{{FIRMA}}_EMUHACC CC2 ON CC2.LOGICALREF=EM2.ACCOUNTREF WHERE EM2.ACCFICHEREF=EMFICHE.LOGICALREF AND SUBSTRING(CC2.CODE,1,1) IN ('6') FOR XML PATH(''), TYPE).value('.','NVARCHAR(MAX)'),1,1,'') AS [Hesap Adı]
 FROM LG_{{FIRMA}}_{{DONEM}}_EMFICHE EMFICHE
 GROUP BY EMFICHE.LOGICALREF  ) AS MUHASEBE ON MUHASEBE.LOGICALREF= INVOICE.LOGICALREF      WHERE STLINE.TRCODE  IN (2,3,7,8,9) AND   STLINE.CANCELLED=0 AND STLINE.LINETYPE  IN (0,1,4)     AND INVOICE.DEVIR=0
GO
